import { describe, expect, it } from 'vitest';
import { targetFlowDiagram } from '../../../../src/domain/diagrams/target-flow-diagram.js';
import type { MappedFlow } from '../../../../src/domain/planning/target-flows.js';
import { mappedFlow } from '../../../support/flow-fixtures.js';
import { fakeOpenAiKey } from '../../../support/secret-fixture.js';

// RF-625, RF-508, ADR-013: the sequence diagram of a target flow is generated by code from the
// checked flow. Participant ids are generated, every label is coded, secrets are masked first and
// a step mapped to no component is not drawn.

const keep = (text: string): string => text;

function stepOf(number: number, component: string | null, action: string) {
  return {
    ...{ claimId: `FLOW-001.c${String(number)}`, text: `Legacy step ${String(number)}.` },
    ...{ touches: null, component, action },
  };
}

const flow: MappedFlow = {
  ...{ cardId: 'FLOW-001', title: 'Place an order' },
  trigger: 'The customer presses Pay.',
  outcome: 'The order is stored.',
  steps: [
    stepOf(1, 'Web', 'Sends it.'),
    stepOf(2, 'Orders', ''),
    stepOf(3, null, ''),
    stepOf(4, 'Web', 'Shows it.'),
  ],
};

describe('targetFlowDiagram', () => {
  it('RF-625 draws the trigger, each component and the numbered steps between them', () => {
    expect(targetFlowDiagram(flow, keep).split('\n')).toEqual([
      'sequenceDiagram',
      '  participant p1 as The customer presses Pay.',
      '  participant p2 as Web',
      '  participant p3 as Orders',
      '  p1->>p2: 1. Sends it.',
      '  p2->>p3: 2. Legacy step 2.',
      '  p3->>p2: 4. Shows it.',
      '  Note over p2: Outcome: The order is stored.',
      '',
    ]);
  });

  it('RF-625 a step mapped to no component is not drawn, but the numbers keep their place', () => {
    const text = targetFlowDiagram(flow, keep);

    expect(text).not.toContain('Legacy step 3');
    expect(text).toContain('4. Shows it');
  });

  it('RF-625 the title stands for a trigger that is not stated, and no outcome draws no note', () => {
    const text = targetFlowDiagram({ ...flow, trigger: '', outcome: '' }, keep);

    expect(text).toContain('participant p1 as Place an order');
    expect(text).not.toContain('Note over');
  });
});

describe('targetFlowDiagram: names and secrets', () => {
  it('RF-508 a component named like the trigger is a participant of its own', () => {
    const text = targetFlowDiagram(
      { ...flow, trigger: 'Web', steps: flow.steps.slice(0, 1) },
      keep,
    );

    expect(text.match(/participant/gu)).toHaveLength(2);
  });

  it('RF-508 hostile names, actions and texts cannot add a statement, a link or HTML', () => {
    const hostile =
      'x"\n  Note over p1: injected;%% {init} <img src=x onerror=1> click p1 call evil() direction TB';

    const text = targetFlowDiagram(mappedFlow(hostile), keep);

    const lines = text.split('\n').filter((line) => line !== '');
    expect(lines[0]).toBe('sequenceDiagram');
    expect(lines).toHaveLength(1 + 2 + 1 + 1);
    expect(text).not.toMatch(/[<>"`%{}]|direction|injected;/u);
    const shape = /^ {2}(participant p\d+ as |p\d+->>p\d+: |Note over p\d+: )/u;
    expect(lines.slice(1).every((line) => shape.test(line))).toBe(true);
  });

  it('RNF-003 masks a secret before a label is coded', () => {
    const mask = (text: string): string => text.replaceAll(fakeOpenAiKey, 'MASKED');

    const text = targetFlowDiagram(mappedFlow(`key ${fakeOpenAiKey}`), mask);

    expect(text).not.toContain(fakeOpenAiKey.slice(8, 30));
    expect(text).toContain('MASKED');
  });
});
